fn summarize_file(input: &std::path::Path, output: &std::path::Path) -> std::io::Result<usize> {
    use std::io::{BufRead, Write};
    if input == output { return Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "输入输出路径相同")); }
    let reader = std::io::BufReader::new(std::fs::File::open(input)?);
    let mut count = 0;
    for line in reader.lines() { if !line?.trim().is_empty() { count += 1; } }
    let mut writer = std::io::BufWriter::new(std::fs::File::create(output)?);
    writeln!(writer, "lines={count}")?;
    writer.flush()?;
    Ok(count)
}

