fn stats(values: &[i32]) -> (usize, i64) {
    fn part(v: &[i32]) -> (usize, i64) {
        (
            v.iter().filter(|&&n| n > 0).count(),
            v.iter().map(|&n| i64::from(n)).sum(),
        )
    }
