enum Task {
    Pending,
    Running(u32),
    Done(u32),
}
fn advance(task: Task, minutes: u32) -> Task {
    match task {
        Task::Pending if minutes == 0 => Task::Pending,
        Task::Pending => {
            if minutes >= 60 {
                Task::Done(minutes)
            } else {
                Task::Running(minutes)
            }
        }
        Task::Running(n) => {
            let total = n.saturating_add(minutes);
            if total >= 60 {
                Task::Done(total)
            } else {
                Task::Running(total)
            }
        }
        done @ Task::Done(_) => done,
    }
}

